def minSplitPenalty(nums, k):
    n = len(nums)
    INF = 10 ** 18
    dp = [INF] * (n + 1)
    dp[0] = 0
    for s in range(n):
        base = dp[s] + k
        cnt = {}
        r = 0
        for e in range(s, n):
            x = nums[e]
            c = cnt.get(x, 0)
            if c == 1:
                r += 2
            elif c >= 2:
                r += 1
            cnt[x] = c + 1
            v = base + r
            if v < dp[e + 1]:
                dp[e + 1] = v
    return dp[n]
